/* =====================================================================
   Horizon Hotel Group | Revenue & Booking Performance
   File:    01_setup_hotel_bookings.sql
   Purpose: Create the HotelAnalytics database, the hotel_bookings table,
            and load 300 SYNTHETIC booking records.
   Engine:  SQL Server (T-SQL). Run in SSMS, in one go (F5).
   Note:    Safe to re-run. It rebuilds the hotel_bookings table from scratch.
   Data:    Synthetic, generated for this portfolio project. Not real guest
            or hotel data. Arrival dates run 2024-01-03 to 2025-12-26.
   ===================================================================== */

IF DB_ID(N'HotelAnalytics') IS NULL
    CREATE DATABASE HotelAnalytics;
GO

USE HotelAnalytics;
GO

DROP TABLE IF EXISTS hotel_bookings;
GO

CREATE TABLE hotel_bookings (
    booking_id                 INT PRIMARY KEY,
    hotel                      VARCHAR(20),     -- City Hotel | Resort Hotel
    arrival_date               DATE,
    lead_time                  INT,             -- days between booking and arrival
    stays_weekend_nights       INT,
    stays_week_nights          INT,
    adults                     INT,
    children                   INT,
    country                    VARCHAR(10),     -- ISO-style 3-letter code
    market_segment             VARCHAR(20),     -- Direct, Online TA, Groups, ...
    distribution_channel       VARCHAR(20),
    customer_type              VARCHAR(20),
    deposit_type               VARCHAR(20),     -- No Deposit | Non Refund | Refundable
    adr                        DECIMAL(10,2),   -- average daily rate
    is_canceled                BIT,             -- 1 = cancelled, 0 = stayed
    total_of_special_requests  INT
);
GO

GO

GO

GO
